@section('content')<div class="superadmin-heading"><div><p class="superadmin-eyebrow">Infra &amp; Security</p><h1>Failed Queue Jobs</h1></div></div><div id="notice" class="sa-notice"></div><section class="sa-card sa-section"><div class="sa-section-header"><div><h2>Failed jobs</h2><p>{{ $jobs->total() }} failed job</p></div><form method="GET"><input name="q" value="{{ $filters['search'] ?? '' }}" class="sa-input" placeholder="Search queue or UUID"><button class="sa-button secondary" type="submit">Filter</button></form></div><div class="sa-table-wrap"><table class="sa-table"><thead><tr><th>Failed at</th><th>Queue</th><th>UUID</th><th>Exception</th><th>Actions</th></tr></thead><tbody>@forelse($jobs as $job)<tr><td>{{ $job->failed_at }}</td><td>{{ $job->queue }}</td><td><small>{{ $job->uuid }}</small></td><td><small>{{ Str::limit($job->exception, 180) }}</small></td><td><button class="sa-button secondary" onclick="retryJob({{ $job->id }})">Retry</button><button class="sa-button danger" onclick="forgetJob({{ $job->id }})">Delete</button></td></tr>@empty<tr><td colspan="5" class="sa-empty">Queue sạch.</td></tr>@endforelse</tbody></table></div><div class="mt-4">{{ $jobs->links() }}</div></section>@endsection
